<div class="table-wrap"><table><thead><tr><th>Belge adı</th><th>Sektör</th><th>Kapsam skoru</th><th>Analiz tarihi</th><th><span class="visually-hidden">İşlem</span></th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><a class="document-link" href="<?= url('report',['id'=>$row['id']]) ?>"><span class="document-icon"><?= icon('file') ?></span><?= e($row['title']) ?></a></td><td><span class="sector-chip"><?= e($row['sector']) ?></span></td><td><span class="score-number <?= $row['score']>=75?'good':($row['score']>=40?'medium':'low') ?>"><?= (int)$row['score'] ?><small>/100</small></span></td><td class="muted nowrap"><?= e(date('d.m.Y · H:i',strtotime($row['created_at']))) ?></td><td><a class="icon-link" aria-label="<?= e($row['title']) ?> raporunu aç" href="<?= url('report',['id'=>$row['id']]) ?>"><?= icon('arrow') ?></a></td></tr><?php endforeach ?></tbody></table></div>
